const fs=require('fs');
for(const f of fs.readdirSync('compositions/frames').filter(x=>x.endsWith('.html')).sort()){
  const s=fs.readFileSync('compositions/frames/'+f,'utf8');
  const root=s.match(/<div[^>]*id=\"root\"[^>]*>/s);
  const id=root&&root[0].match(/data-composition-id=\"([^\"]+)\"/);
  const dur=root&&root[0].match(/data-duration=\"([^\"]+)\"/);
  const wh=root&&/data-width=\"1920\"/.test(root[0])&&/data-height=\"1080\"/.test(root[0]);
  const ids=[...s.matchAll(/\bid=\"([^\"]+)\"/g)].map(m=>m[1]);
  const badIds=ids.filter(i=>!/^[A-Za-z]/.test(i));
  const tl=s.match(/window\.__timelines\[\"([^\"]+)\"\]/);
  console.log(f, '| root id:', id&&id[1], '| dur:', dur&&dur[1], '| wh:', wh, '| tl:', tl&&tl[1], '| ids:', ids.length, '| badIds:', JSON.stringify(badIds), '| fontface:', /@font-face/.test(s), '| audio:', /<audio/.test(s), '| cssTransition:', /transition\s*:/.test(s), '| random:', /Math\.random|Date\.now|performance\.now/.test(s));
}
